import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { cpSync, existsSync, mkdtempSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { harness } from '/Users/davidr/.t3/worktrees/effectory/t3-21743e89/scripts/upgrade-proof/process.mjs';
const base = '/tmp/effectory-rollback-receipts';
const target = '/tmp/effectory-http-disconnect/release2-bin/effectory-darwin-arm64';
const hash = (file) => createHash('sha256').update(readFileSync(file)).digest('hex');
const inventory = (root, relative = '') => Object.fromEntries(readdirSync(path.join(root, relative)).sort().flatMap(name => {
  const rel = path.join(relative, name);
  if (rel.startsWith('.effectory/state.sqlite.owner')) return [];
  const full = path.join(root, rel);
  return statSync(full).isDirectory() ? Object.entries(inventory(root, rel)) : [[rel, hash(full)]];
}));
const results = [];
for (const format of ['format2', 'format3']) {
  const certificate = JSON.parse(readFileSync(`/tmp/effectory-http-disconnect/edge-${format}-release/certification.json`, 'utf8'));
  const original = certificate.results['wait-rollback'].result;
  const receipt = original.legacySeed.receipt;
  const planId = receipt.plan.planId;
  const root = path.dirname(original.legacySeed.plan.recoveryCopy);
  const restored = path.join(root, 'restored');
  assert.ok(existsSync(path.join(restored, '.effectory/upgrade-history', planId + '.json')));
  assert.ok(Date.now() > receipt.plan.expiresAt, 'exercise expired completed receipt');
  const work = mkdtempSync(path.join(base, 'copy-'));
  const repo = path.join(work, 'repository');
  cpSync(restored, repo, { recursive: true, errorOnExist: true, force: false });
  // Capture the restored state; commands must not recreate plans or migration work.
  const before = inventory(repo);
  const h = harness(work), commands = [];
  try {
    for (const [name, binary] of [['predecessor', certificate.predecessor.filename], ['current', target]]) {
      for (const action of ['inspect', 'apply']) {
        const result = await h.cli(binary, repo, ['upgrade', action, planId]);
        assert.deepEqual(action === 'inspect' ? result.transition : result, receipt);
        assert.deepEqual(inventory(repo), before);
        commands.push({ host: name, action, exit: 0, receiptIdentical: true, persistentFilesUnchanged: true });
      }
    }
    results.push({ sourceStorage: original.sourceStorage, originalRestoredRepository: restored, scratchRepository: repo, predecessor: certificate.predecessor, targetSha256: hash(target), planId, expiresAt: receipt.plan.expiresAt, verifiedAt: Date.now(), files: Object.keys(before).length, commands });
  } finally { await h.close(); }
}
writeFileSync(path.join(base, 'results.json'), JSON.stringify(results, null, 2) + '\n');
console.log(JSON.stringify(results, null, 2));
